// Parses an absolute http(s) URL without the `URL` global, which n8n's Code
// node sandbox does not provide. Returns null for anything it will not vouch
// for, so every caller can treat null as "refuse this value".
function parseHttpUrl(value) {
  const raw = (value === null || value === undefined ? '' : String(value)).trim();
  if (!raw) return null;

  // No spaces, tabs, newlines or control characters anywhere. A URL carrying
  // one is either malformed or an attempt to hide a second value inside the
  // first, and neither is worth guessing about.
  for (let i = 0; i < raw.length; i++) {
    const code = raw.charCodeAt(i);
    if (code <= 0x20 || code === 0x7f) return null;
  }

  // Backslashes are rejected rather than normalised. Browsers treat a
  // backslash as "/", so an authority written with one can read as a hostile
  // host in a browser and a trusted host in a naive parser. Scout refuses the
  // ambiguity instead of picking a side.
  if (raw.indexOf('\\') !== -1) return null;

  const parts = /^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#[\s\S]*)?$/.exec(raw);
  if (!parts) return null;

  const protocol = parts[1].toLowerCase() + ':';
  if (protocol !== 'http:' && protocol !== 'https:') return null;

  const authority = parts[2];
  if (!authority) return null;

  // Split user information off the authority. Scout never sends credentials in
  // a URL, but workflow 01 has to be able to see that someone tried.
  let username = '';
  let password = '';
  let hostport = authority;
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    const userinfo = authority.slice(0, at);
    if (!userinfo) return null;
    hostport = authority.slice(at + 1);
    const sep = userinfo.indexOf(':');
    username = sep === -1 ? userinfo : userinfo.slice(0, sep);
    password = sep === -1 ? '' : userinfo.slice(sep + 1);
  }
  if (!hostport) return null;

  // Separate an optional port so it can never be mistaken for part of the host.
  let hostname = hostport;
  let port = '';
  if (hostport.charAt(0) === '[') {
    const close = hostport.indexOf(']');
    if (close === -1) return null;
    hostname = hostport.slice(0, close + 1);
    const rest = hostport.slice(close + 1);
    if (rest) {
      if (rest.charAt(0) !== ':') return null;
      port = rest.slice(1);
    }
  } else {
    const sep = hostport.indexOf(':');
    if (sep !== -1) {
      hostname = hostport.slice(0, sep);
      port = hostport.slice(sep + 1);
    }
    // Only ASCII hosts are accepted. An internationalised name would need
    // punycode conversion to compare safely, and Scout has no need of one.
    if (!/^[A-Za-z0-9._~%-]+$/.test(hostname)) return null;
  }
  if (!hostname) return null;
  if (port && !/^[0-9]+$/.test(port)) return null;

  const pathname = parts[3] || '/';
  const search = parts[4] || '';
  const hash = parts[5] || '';
  const host = port ? hostname + ':' + port : hostname;
  const href = protocol + '//' + host + pathname + search + hash;

  return {
    protocol: protocol,
    username: username,
    password: password,
    hostname: hostname,
    port: port,
    host: host,
    pathname: pathname,
    search: search,
    hash: hash,
    href: href,
    toString: function () { return href; }
  };
}

// VALIDATE SCOUT SETUP + FORM INPUT
// Runs before any Anthropic or Notion request. Every message names either the
// Scout Setup field or the form field the operator has to fix.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

const model = (cfg.anthropicModel || '').toString().trim();
if (!model) {
  problems.push('anthropicModel is empty. Set the Anthropic model id to classify with.');
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

const VALID_SOURCES = [
  'LinkedIn post', 'LinkedIn people', 'HubSpot Community',
  'Reddit', 'Job posting', 'Partner directory', 'Referral'
];

const out = [];

for (const item of $input.all()) {
  const form = item.json || {};
  const errors = [];

  const name = (form['Name'] || '').toString().trim();
  const note = (form['What you saw'] || '').toString().trim();
  const company = (form['Company'] || '').toString().trim();
  const rawUrl = (form['URL'] || '').toString().trim();
  const source = (form['Source'] || '').toString().trim();

  if (name.length < 2 || name.length > 200) {
    errors.push('Name must be between 2 and 200 characters.');
  }
  if (note.length < 10 || note.length > 5000) {
    errors.push('What you saw must be between 10 and 5000 characters.');
  }
  if (company.length > 200) {
    errors.push('Company must be 200 characters or fewer.');
  }
  if (!VALID_SOURCES.includes(source)) {
    errors.push('Source must be one of: ' + VALID_SOURCES.join(', ') + '.');
  }

  // The URL is optional. When supplied it has to be an absolute http or https
  // URL. Scout only records it. It never fetches the page behind it, whichever
  // platform the label names.
  let url = '';
  if (rawUrl) {
    const parsed = parseHttpUrl(rawUrl);
    if (!parsed) {
      // Separate "wrong scheme" from "not a URL", because the two need
      // different corrections from whoever submitted the form.
      const hasScheme = /^[A-Za-z][A-Za-z0-9+.-]*:/.test(rawUrl);
      errors.push(hasScheme && !/^https?:/i.test(rawUrl)
        ? 'URL must use http or https.'
        : 'URL is not a valid absolute URL.');
    } else {
      url = parsed.href;
    }
  }

  if (errors.length > 0) {
    throw new Error('Manual signal rejected. ' + errors.join(' '));
  }

  out.push({ json: { name, note, company, url, source } });
}

return out;

// BUILD THE CLASSIFICATION REQUEST
// One Anthropic request per submitted signal. The system prompt fixes the
// output contract; every enum is re-checked downstream so a drifting model
// can never write an invalid value into Notion.
const cfg = $('Scout Setup').first().json;
const model = (cfg.anthropicModel || '').toString().trim();

const SYSTEM = [
  'You qualify inbound RevOps signals for a HubSpot data and automation consultancy.',
  'You are given one signal that a human operator recorded by hand.',
  'Return ONLY a JSON object, with no prose and no code fence, using exactly these keys:',
  '{"relevant": boolean, "warmth_tier": string, "pain_areas": string[], "persona_type": string, "track": string, "next_action": string, "best_angle": string, "draft": string}',
  'warmth_tier is one of: Tier 1 (hot), Tier 2 (warm), Tier 3 (cool), Tier 4 (cold).',
  'pain_areas is a subset of: Routing, Lifecycle, Dedupe, Enrichment, Data quality, Reporting.',
  'persona_type is one of: ICP buyer, ICP practitioner, Partner / consultant, Peer / networker, Unknown.',
  'track is one of: Sales (ICP), Connector, Unknown.',
  'next_action is one of: Comment, DM, Connect, Monitor, Ignore.',
  'best_angle is the single most useful diagnostic question an operator could ask this person.',
  'draft is a short message for a human to review, edit and send. Under 90 words, peer to peer, no emojis, no hashtags, no pitch and no meeting request.'
].join('\n');

const out = [];

for (const item of $input.all()) {
  const s = item.json || {};
  const userContent = [
    'PERSON: ' + s.name,
    'COMPANY: ' + (s.company || 'unknown'),
    'SOURCE: ' + s.source,
    'URL: ' + (s.url || 'not supplied'),
    'WHAT THE OPERATOR SAW: ' + s.note
  ].join('\n');

  out.push({ json: {
    name: s.name,
    company: s.company,
    source: s.source,
    url: s.url,
    note: s.note,
    _anthropicBody: {
      model,
      max_tokens: 700,
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }]
    }
  }});
}

return out;

// MAP THE MODEL VERDICT ONTO THE PUBLIC NOTION SCHEMA
// Pairs each Anthropic response with its submission by index. Unparseable or
// out-of-enum output never blocks the row: it lands with status "Needs review"
// so the operator sees the submission instead of losing it.
const DATABASE_ID = ($('Scout Setup').first().json.notionDatabaseId || '').toString().trim();

const VALID_TIERS = ['Tier 1 (hot)', 'Tier 2 (warm)', 'Tier 3 (cool)', 'Tier 4 (cold)'];
const VALID_PAIN_AREAS = ['Routing', 'Lifecycle', 'Dedupe', 'Enrichment', 'Data quality', 'Reporting'];
const VALID_PERSONAS = ['ICP buyer', 'ICP practitioner', 'Partner / consultant', 'Peer / networker', 'Unknown'];
const VALID_TRACKS = ['Sales (ICP)', 'Connector', 'Unknown'];
const VALID_ACTIONS = ['Comment', 'DM', 'Connect', 'Monitor', 'Ignore'];

// Scout records a LinkedIn URL the operator typed, but never retrieves it.
// Routing it to its own property keeps that distinction visible in Notion.
const LINKEDIN_SOURCES = ['LinkedIn post', 'LinkedIn people'];

function cap(value) {
  return (value === null || value === undefined ? '' : String(value)).slice(0, 1900);
}

function parseVerdict(response) {
  let text = '';
  try { text = (response.content || []).map((c) => c.text || '').join('').trim(); }
  catch (e) { text = ''; }
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) { return null; }
}

const sources = $('Build Claude Request').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const src = (sources[i] && sources[i].json) || {};
  const verdict = parseVerdict(inputs[i].json || {});

  const properties = {
    'Name': { title: [{ text: { content: cap(src.name || 'Manual signal') } }] },
    'Signal': { rich_text: [{ text: { content: cap(src.note || '') } }] },
    'Source': { select: { name: src.source } },
    'Replied': { checkbox: false }
  };

  if (src.company) {
    properties['Company'] = { rich_text: [{ text: { content: cap(src.company) } }] };
  }
  if (src.url) {
    const key = LINKEDIN_SOURCES.includes(src.source) ? 'LinkedIn URL' : 'Source URL';
    properties[key] = { url: src.url };
  }

  if (!verdict) {
    properties['Warmth tier'] = { select: { name: 'Tier 4 (cold)' } };
    properties['Persona type'] = { select: { name: 'Unknown' } };
    properties['Track'] = { select: { name: 'Unknown' } };
    properties['Next action'] = { select: { name: 'Monitor' } };
    properties['Status'] = { select: { name: 'Needs review' } };
    properties['Evidence'] = { rich_text: [{ text: { content: 'Classifier returned an unusable response. Review by hand.' } }] };
  } else {
    const painAreas = (Array.isArray(verdict.pain_areas) ? verdict.pain_areas : [])
      .filter((p) => VALID_PAIN_AREAS.includes(p));

    properties['Warmth tier'] = {
      select: { name: VALID_TIERS.includes(verdict.warmth_tier) ? verdict.warmth_tier : 'Tier 4 (cold)' }
    };
    properties['Persona type'] = {
      select: { name: VALID_PERSONAS.includes(verdict.persona_type) ? verdict.persona_type : 'Unknown' }
    };
    properties['Track'] = {
      select: { name: VALID_TRACKS.includes(verdict.track) ? verdict.track : 'Unknown' }
    };
    properties['Next action'] = {
      select: { name: VALID_ACTIONS.includes(verdict.next_action) ? verdict.next_action : 'Monitor' }
    };
    properties['Status'] = { select: { name: 'New' } };
    if (painAreas.length > 0) {
      properties['Pain area'] = { multi_select: painAreas.map((p) => ({ name: p })) };
    }
    if (verdict.best_angle) {
      properties['Best angle'] = { rich_text: [{ text: { content: cap(verdict.best_angle) } }] };
    }
    // The draft is a suggestion. Scout writes it to Notion and stops there.
    if (verdict.draft) {
      properties['Draft'] = { rich_text: [{ text: { content: cap(verdict.draft) } }] };
    }
  }

  out.push({ json: {
    recordName: src.name,
    needsReview: !verdict,
    _notionBody: { parent: { database_id: DATABASE_ID }, properties }
  }});
}

return out;
